from taf.ul.ettf.msg_capture.condition_wrappers.condition import Condition, Verifiable
from taf.ul.ettf.msg_capture.condition_wrappers.utils import get_matchers_with_tags, PartialMatch, \
    UNEXPECTED_PACKET_MISMATCH, UNEXISTING_PACKET, UNEXISTING_RESULT
from taf.ul.ettf.msg_capture.expectation_builders import Expected, Unexpected
from taf.ul.ettf.ta_matchers.matchers import MatchingError, MatchingResult, Mismatch
from taf.ul.ettf.logger import custom_logger
from taf.ul.ettf.msg_capture.capture_condition_tracker import ConditionNotMet


logger = custom_logger('NonOrdered')


class NonOrdered(Condition, Verifiable):
    def __init__(self, *matchers):
        self._matchers = get_matchers_with_tags(matchers, Expected.tags)
        self._unexpected_matchers = get_matchers_with_tags(matchers, Unexpected.tags)
        self._used_matchers = []
        self._callbacks = []

    def __eq__(self, other):
        if not isinstance(other, NonOrdered):
            return False
        return self.matchers == other.matchers

    @property
    def matchers(self):
        return self._matchers + self._unexpected_matchers

    def get_name(self):
        return 'Without order'

    def _run_callbacks_for_unused_matchers(self):
        for matcher in self._get_unused_matchers():
            for callback in self._callbacks:
                callback(matcher, UNEXISTING_PACKET, UNEXISTING_RESULT)
                self._used_matchers.append(matcher)

    def _get_unused_matchers(self):
        return [m for m in self._matchers if m not in self._used_matchers]

    def append_callback(self, callback):
        self._callbacks.append(callback)
        for m in self._matchers:
            m.append_callback(callback)

    def verify(self, packets):
        result = None
        for captured_message in packets:
            if self._no_matchers_left():
                return
            result = self.validate(captured_message)

        if not self._get_final_result():
            self._run_callbacks_for_unused_matchers()
            raise ConditionNotMet(result)

    def validate(self, packet):
        if self._no_matchers_left():
            raise MatchingError([Mismatch('Matcher is empty!')])

        local_mismatches = []
        for matcher in self._unexpected_matchers:
            local_mismatches.extend(self._match_packet_as_unexpected(packet, matcher))
            if local_mismatches:
                raise ConditionNotMet(local_mismatches)

        for matcher in self._matchers:
            self._used_matchers.append(matcher)
            try:
                self._match_packet(matcher, packet)
                self._packet_matched(matcher)
                break
            except MatchingError as error:
                local_mismatches.append(error.mismatches)

        if self._no_matchers_left():
            return MatchingResult([])

        return MatchingResult(local_mismatches) if local_mismatches else PartialMatch()

    def _match_packet_as_unexpected(self, packet, matcher):
        local_mismatches = []
        try:
            matcher.match(packet)
            local_mismatches.append(UNEXPECTED_PACKET_MISMATCH)
            for callback in self._callbacks:
                callback(matcher, packet, MatchingResult(local_mismatches))
        except MatchingError:
            pass

        return local_mismatches

    def _packet_matched(self, matcher):
        self._matchers.remove(matcher)

    def _no_matchers_left(self):
        return not self._matchers and not self._unexpected_matchers

    def _get_final_result(self):
        return not self._matchers
